-- Persistent EWO + approved garment colour registry. No source cells or quantities are changed.
CREATE TABLE IF NOT EXISTS ekwl_fabric_master_identities (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,display_no BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,ewo CHAR(6) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,master_colour TEXT NOT NULL,colour_key_sha256 CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,status VARCHAR(16) NOT NULL,match_method VARCHAR(24) NOT NULL,evidence_digest CHAR(64) CHARACTER SET ascii NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),UNIQUE KEY display_no(display_no),UNIQUE KEY master_colour(ewo,colour_key_sha256),UNIQUE KEY identity_ewo(id,ewo)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS ekwl_fabric_master_aliases (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,master_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,ewo CHAR(6) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,source_name VARCHAR(16) CHARACTER SET ascii NOT NULL,scope_key CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,original_colour TEXT NOT NULL,match_method VARCHAR(24) NOT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,mapping_id CHAR(36) CHARACTER SET ascii NULL,source_references LONGTEXT NOT NULL,UNIQUE KEY alias_master(id,master_id),FOREIGN KEY(master_id,ewo) REFERENCES ekwl_fabric_master_identities(id,ewo)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS ekwl_fabric_master_events (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,master_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,event_type VARCHAR(32) CHARACTER SET ascii NOT NULL,actor_id CHAR(36) CHARACTER SET ascii NOT NULL,evidence LONGTEXT NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(master_id) REFERENCES ekwl_fabric_master_identities(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
